texto:
[Meta]
Version=4

[BulletImpact]
Enabled={0}

[Debug]
; True = also write the per-frame DIAG lines to BulletImpact.log (hits, kill shots and crippling are always logged).
LogHits={1}

[Wounds]
; Shattered spine / pelvis / knee / leg bones put people down for good (they crawl), a broken neck
; paralyzes, a shattered foot leaves a limp. Decided from each hit's X-ray.
Crippling={2}
; Your weapon damage against everyone, 1.0 = vanilla. Lower = people soak more hits before dying.
PlayerDamage={3}
; A shot whose X-ray destroys the brain or pierces the heart kills outright, whatever the damage.
KillShots={4}

[XRay]
; X-ray log (F11, then Tab): the newest MaxEntries people and the newest MaxEntries animals are kept in enRAGE\xray_log.json.
MaxEntries={5}
; Detail: Auto (best that fits the rect limit) / High / Medium / Low.
Detail={6}
; The game's per-frame limit on script-drawn rects (it silently drops the rest). The X-ray uses
; whatever the menu leaves under it. Measure it with the calibration screen: K in the X-ray log.
RectLimit={7}
; Every letter of text on screen seems to come out of the same per-frame limit (the X-ray report's text left the skeleton
; half drawn). The X-ray budget takes this many units off per drawn letter. Raise it if bones still go missing.
GlyphCost={8}
